// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAuditEvents List append-only safe audit events
	// (GET /audit-events)
	ListAuditEvents(w http.ResponseWriter, r *http.Request, params ListAuditEventsParams)
	// AuthorizeBrowserHandoff Authorize one browser handoff as the Controller owner
	// (POST /browser-handoff-authorizations)
	AuthorizeBrowserHandoff(w http.ResponseWriter, r *http.Request, params AuthorizeBrowserHandoffParams)
	// CreateBrowserHandoff Create a non-authorizing browser handoff code
	// (POST /browser-handoffs)
	CreateBrowserHandoff(w http.ResponseWriter, r *http.Request)
	// ClaimBrowserHandoff Claim an owner-approved browser handoff
	// (POST /browser-handoffs/claim)
	ClaimBrowserHandoff(w http.ResponseWriter, r *http.Request)
	// GetConfiguration Read the non-secret desired configuration
	// (GET /configuration)
	GetConfiguration(w http.ResponseWriter, r *http.Request)
	// ApplyConfiguration Atomically replace desired configuration and append its audit event
	// (PUT /configuration)
	ApplyConfiguration(w http.ResponseWriter, r *http.Request, params ApplyConfigurationParams)
	// ExportConfiguration Export versioned non-secret YAML
	// (GET /configuration/export)
	ExportConfiguration(w http.ResponseWriter, r *http.Request)
	// StreamEvents Stream level-triggered management invalidations
	// (GET /events)
	StreamEvents(w http.ResponseWriter, r *http.Request, params StreamEventsParams)
	// CreateJoinCode Create and deliver a one-time join code
	// (POST /join-codes)
	CreateJoinCode(w http.ResponseWriter, r *http.Request, params CreateJoinCodeParams)
	// CancelJoinCode Cancel an unconsumed join code by its non-secret identifier
	// (DELETE /join-codes/{tokenId})
	CancelJoinCode(w http.ResponseWriter, r *http.Request, tokenId string, params CancelJoinCodeParams)
	// ListNodes List enrolled nodes and last-known state
	// (GET /nodes)
	ListNodes(w http.ResponseWriter, r *http.Request)
	// DrainNode Stop assigning new work to a node
	// (POST /nodes/{nodeId}/drain)
	DrainNode(w http.ResponseWriter, r *http.Request, nodeId NodeID, params DrainNodeParams)
	// ResumeNode Reconcile a drained node before it can advertise capacity
	// (POST /nodes/{nodeId}/resume)
	ResumeNode(w http.ResponseWriter, r *http.Request, nodeId NodeID, params ResumeNodeParams)
	// RevokeNode Revoke a node credential
	// (POST /nodes/{nodeId}/revoke)
	RevokeNode(w http.ResponseWriter, r *http.Request, nodeId NodeID, params RevokeNodeParams)
	// GetOverview Read the safe fleet overview
	// (GET /overview)
	GetOverview(w http.ResponseWriter, r *http.Request)
	// ListRuns List safe execution history
	// (GET /runs)
	ListRuns(w http.ResponseWriter, r *http.Request)
	// DeleteSession End the current administrator session
	// (DELETE /session)
	DeleteSession(w http.ResponseWriter, r *http.Request, params DeleteSessionParams)
	// GetSession Read the current session and in-memory CSRF token
	// (GET /session)
	GetSession(w http.ResponseWriter, r *http.Request)
	// CreateSession Start an owner-authorized loopback administrator session
	// (POST /session)
	CreateSession(w http.ResponseWriter, r *http.Request, params CreateSessionParams)
	// GetSetup Read setup readiness without returning credentials
	// (GET /setup)
	GetSetup(w http.ResponseWriter, r *http.Request)
	// ListTargets List configured targets and last-known GitHub freshness
	// (GET /targets)
	ListTargets(w http.ResponseWriter, r *http.Request)
}

