// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/session", wrapper.DeleteSession)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/session", wrapper.GetSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/session", wrapper.CreateSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/browser-handoffs", wrapper.CreateBrowserHandoff)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/browser-handoffs/claim", wrapper.ClaimBrowserHandoff)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/browser-handoff-authorizations", wrapper.AuthorizeBrowserHandoff)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/setup", wrapper.GetSetup)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/overview", wrapper.GetOverview)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/nodes", wrapper.ListNodes)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/nodes/{nodeId}/drain", wrapper.DrainNode)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/nodes/{nodeId}/resume", wrapper.ResumeNode)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/nodes/{nodeId}/revoke", wrapper.RevokeNode)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/targets", wrapper.ListTargets)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/runs", wrapper.ListRuns)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/audit-events", wrapper.ListAuditEvents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/join-codes", wrapper.CreateJoinCode)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/join-codes/{tokenId}", wrapper.CancelJoinCode)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/configuration", wrapper.GetConfiguration)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/configuration", wrapper.ApplyConfiguration)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/configuration/export", wrapper.ExportConfiguration)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/events", wrapper.StreamEvents)

	return m
}

